import React from 'react';
import { Link } from 'react-router-dom';
import MotionReveal, { staggerDelay } from '../../motion/MotionReveal.jsx';
import AnimatedText from '../../motion/AnimatedText.jsx';
import OutlineIcon from '../icons/OutlineIcon.jsx';
import './StatsBanner.css';

const STATS = [
  { value: '1000+', label: 'Students Guided', icon: 'cap' },
  { value: '150+', label: 'Partner Colleges', icon: 'book' },
  {
    value: '2',
    label: 'Live College Predictors',
    icon: 'chart',
    accent: true,
    action: { to: '/kcet-predictor', text: 'Try it free' },
  },
  { value: '24/7', label: 'Counsellor Support', icon: 'chat' },
];

export default function StatsBanner() {
  return (
    <section className="mmc-stats-banner" aria-label="Platform highlights">
      <div className="mmc-stats-banner-orbs" aria-hidden="true">
        <span className="mmc-stats-orb mmc-stats-orb--orange" />
        <span className="mmc-stats-orb mmc-stats-orb--blue" />
      </div>
      <div className="container mmc-stats-banner-grid">
        {STATS.map((stat, index) => (
          <MotionReveal
            key={stat.label}
            className={`mmc-stats-card${stat.accent ? ' is-accent' : ''}`}
            delay={staggerDelay(index, 80)}
          >
            <div className="mmc-stats-card-spin" aria-hidden="true" />
            <article className="mmc-stats-item">
              <span className="mmc-stats-icon">
                <OutlineIcon name={stat.icon} size={20} />
              </span>
              <strong>{stat.value}</strong>
              <span className="mmc-stats-label">
                <AnimatedText delay={staggerDelay(index, 50)}>{stat.label}</AnimatedText>
              </span>
              {stat.action ? (
                <Link to={stat.action.to} className="mmc-stats-chip">
                  {stat.action.text} <OutlineIcon name="arrow" size={14} />
                </Link>
              ) : null}
            </article>
          </MotionReveal>
        ))}
      </div>
    </section>
  );
}
